class Solution:
    def numWays(self, words: list[str], target: str) -> int:
        MOD = 10**9 + 7
        m = len(words[0])
        n = len(target)
        freq = [[0] * 26 for _ in range(m)]
        for word in words:
            for i, c in enumerate(word):
                freq[i][ord(c) - ord('a')] += 1
        dp = [0] * (n + 1)
        dp[0] = 1
        for col in range(m):
            for j in range(min(n, col + 1), 0, -1):
                dp[j] = (dp[j] + dp[j - 1] * freq[col][ord(target[j - 1]) - ord('a')]) % MOD
        return dp[n]

